WITH reason_agg AS ( SELECT cp.cp_catalog_page_id AS cp_id, cp.cp_department, r.r_reason_desc, cd.cd_gender, COUNT(*) AS return_events, SUM(cr.cr_return_amount) AS total_return_amount FROM catalog_returns cr JOIN catalog_page cp ON cr.cr_catalog_page_sk = cp.cp_catalog_page_sk JOIN reason r ON cr.cr_reason_sk = r.r_reason_sk JOIN customer_demographics cd ON cr.cr_returning_cdemo_sk = cd.cd_demo_sk WHERE cr.cr_return_quantity >= 5 GROUP BY cp.cp_catalog_page_id, cp.cp_department, r.r_reason_desc, cd.cd_gender ), ranked_reason AS ( SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, RANK() OVER (PARTITION BY cp_id ORDER BY total_return_amount DESC) AS rnk_amount FROM reason_agg ) SELECT cp_id, cp_department, r_reason_desc, cd_gender, return_events, total_return_amount, CASE WHEN rnk_amount <= 1 THEN 'Highest Return Amount' ELSE 'Other' END AS amount_category FROM ranked_reason WHERE return_events > 2 ORDER BY total_return_amount DESC, cp_id
